22: window.loadHistory = (function() {
23:     // Date of last seen item.
24:     var lastItemDate = null;
25: 
26:     // Each request for new items includes the time of the last item and an
27:     // offset. The offset is equal to the number of items from the previous
28:     // request that had time=nextTime, and causes the next request to skip
29:     // those items to avoid duplicates.
30:     var nextTime = null;
31:     var nextOffset = 0;
32: 
33:     // The URL to fetch data from.
34:     var DATA_URL = "qute://history/data";
35: 
36:     // Various fixed elements
37:     var EOF_MESSAGE = document.getElementById("eof");
38:     var LOAD_LINK = document.getElementById("load");
39:     var HIST_CONTAINER = document.getElementById("hist-container");
40: 
41:     /**
42:      * Finds or creates the session table>tbody to which item with given date
43:      * should be added.
44:      *
45:      * @param {Date} date - the date of the item being added.
46:      * @returns {Element} the element to which new rows should be added.
47:      */
48:     function getSessionNode(date) {
49:         // Find/create table
50:         var tableId = ["hist", date.getDate(), date.getMonth(),
51:             date.getYear()].join("-");
52:         var table = document.getElementById(tableId);
53:         if (table === null) {
54:             table = document.createElement("table");
55:             table.id = tableId;
56: 
57:             // Caption contains human-readable date
58:             var caption = document.createElement("caption");
59:             caption.className = "date";
60:             var options = {
61:                 "weekday": "long",
62:                 "year": "numeric",
63:                 "month": "long",
64:                 "day": "numeric",
65:             };
66:             caption.innerHTML = date.toLocaleDateString("en-US", options);
67:             table.appendChild(caption);
68: 
69:             // Add table to page
70:             HIST_CONTAINER.appendChild(table);
71:         }
72: 
73:         // Find/create tbody
74:         var tbody = table.lastChild;
75:         if (tbody.tagName !== "TBODY") {
76:             tbody = document.createElement("tbody");
77:             table.appendChild(tbody);
78:         }
79: 
80:         // Create session-separator and new tbody if necessary
81:         if (tbody.lastChild !== null && lastItemDate !== null &&
82:                 window.SESSION_INTERVAL > 0) {
83:             var interval = lastItemDate.getTime() - date.getTime();
84:             if (interval > window.SESSION_INTERVAL) {
85:                 // Add session-separator
86:                 var sessionSeparator = document.createElement("td");
87:                 sessionSeparator.className = "session-separator";
88:                 sessionSeparator.colSpan = 2;
89:                 sessionSeparator.innerHTML = "&#167;";
90:                 table.appendChild(document.createElement("tr"));
91:                 table.lastChild.appendChild(sessionSeparator);
92: 
93:                 // Create new tbody
94:                 tbody = document.createElement("tbody");
95:                 table.appendChild(tbody);
96:             }
97:         }
98: 
99:         return tbody;
100:     }
101: 
102:     /**
103:      * Given a history item, create and return <tr> for it.
104:      *
105:      * @param {string} itemUrl - The url for this item.
106:      * @param {string} itemTitle - The title for this item.
107:      * @param {string} itemTime - The formatted time for this item.
108:      * @returns {Element} the completed tr.
109:      */
110:     function makeHistoryRow(itemUrl, itemTitle, itemTime) {
111:         var row = document.createElement("tr");
112: 
113:         var title = document.createElement("td");
114:         title.className = "title";
115:         var link = document.createElement("a");
116:         link.href = itemUrl;
117:         link.innerHTML = itemTitle;
118:         var host = document.createElement("span");
119:         host.className = "hostname";
120:         host.innerHTML = link.hostname;
121:         title.appendChild(link);
122:         title.appendChild(host);
123: 
124:         var time = document.createElement("td");
125:         time.className = "time";
126:         time.innerHTML = itemTime;
127: 
128:         row.appendChild(title);
129:         row.appendChild(time);
130: 
131:         return row;
132:     }
133: 
134:     /**
135:      * Get JSON from given URL.
136:      *
137:      * @param {string} url - the url to fetch data from.
138:      * @param {function} callback - the function to callback with data.
139:      * @returns {void}
140:      */
141:     function getJSON(url, callback) {
142:         var xhr = new XMLHttpRequest();
143:         xhr.open("GET", url, true);
144:         xhr.responseType = "json";
145:         xhr.onload = function() {
146:             var status = xhr.status;
147:             callback(status, xhr.response);
148:         };
149:         xhr.send();
150:     }
151: 
152:     /**
153:      * Receive history data from qute://history/data.
154:      *
155:      * @param {Number} status - The status of the query.
156:      * @param {Array} history - History data.
157:      * @returns {void}
158:      */
159:     function receiveHistory(status, history) {
160:         if (history === null) {
161:             return;
162:         }
163: 
164:         if (history.length === 0) {
165:             // Reached end of history
166:             window.onscroll = null;
167:             EOF_MESSAGE.style.display = "block";
168:             LOAD_LINK.style.display = "none";
169:             return;
170:         }
171: 
172:         nextTime = history[history.length - 1].time;
173:         nextOffset = 0;
174: 
175:         for (var i = 0, len = history.length; i < len; i++) {
176:             var item = history[i];
177:             // python's time.time returns seconds, but js Date expects ms
178:             var currentItemDate = new Date(item.time * 1000);
179:             getSessionNode(currentItemDate).appendChild(makeHistoryRow(
180:                 item.url, item.title, currentItemDate.toLocaleTimeString()
181:             ));
182:             lastItemDate = currentItemDate;
183:             if (item.time === nextTime) {
184:                 nextOffset++;
185:             }
186:         }
187:     }
188: 
189:     /**
190:      * Load new history.
191:      * @return {void}
192:      */
193:     function loadHistory() {
194:         var url = DATA_URL.concat("?offset=", nextOffset.toString());
195:         if (nextTime === null) {
196:             getJSON(url, receiveHistory);
197:         } else {
198:             url = url.concat("&start_time=", nextTime.toString());
199:             getJSON(url, receiveHistory);
200:         }
201:     }
202: 
203:     return loadHistory;
204: })();

